export function createDebouncer(waitMs) {
  const timers = new Map()

  function schedule(key, callback) {
    cancel(key)

    const t = setTimeout(() => {
      timers.delete(key)
      void Promise.resolve()
        .then(callback)
        .catch(() => {})
    }, waitMs)

    timers.set(key, t)
  }

  function cancel(key) {
    const t = timers.get(key)
    if (!t) return false

    clearTimeout(t)
    timers.delete(key)
    return true
  }

  function cancelAll() {
    for (const t of timers.values()) {
      clearTimeout(t)
    }
    timers.clear()
  }

  return { schedule, cancel, cancelAll }
}
